import{_ as a,o as i,c as o,ai as r}from"./chunks/framework.C33Uq6m-.js";const b=JSON.parse('{"title":"导出你的数据","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/export.md","filePath":"zh/guide/export.md"}'),e={name:"zh/guide/export.md"};function d(l,t,s,n,h,u){return i(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="导出你的数据" tabindex="-1">导出你的数据 <a class="header-anchor" href="#导出你的数据" aria-label="Permalink to &quot;导出你的数据&quot;">​</a></h1><p>LLMxRay 会产生大量数据 —— 基准测试、会话、对话、工具定义和系统报告。你创建的每一份数据都可以导出。在你主动选择分享之前，数据始终留在本地。</p><h2 id="哪些内容可以导出" tabindex="-1">哪些内容可以导出 <a class="header-anchor" href="#哪些内容可以导出" aria-label="Permalink to &quot;哪些内容可以导出&quot;">​</a></h2><table tabindex="0"><thead><tr><th>页面</th><th>格式</th><th>包含什么</th></tr></thead><tbody><tr><td>对比</td><td>JSON、Markdown、分享</td><td>提示词、输出、指标、Token 税</td></tr><tr><td>基准测试</td><td>JSON、CSV、Markdown</td><td>题目、答案、准确率、分类别结果</td></tr><tr><td>会话</td><td>JSON、Markdown、Token CSV</td><td>提示词、回复、指标、逐 token 延迟</td></tr><tr><td>对话</td><td>JSON、Markdown、纯文本</td><td>带时间戳的完整对话</td></tr><tr><td>工具工坊</td><td>JSON</td><td>工具定义及其实现</td></tr><tr><td>系统</td><td>JSON、Markdown</td><td>硬件、Ollama 状态、模型、存储</td></tr></tbody></table><h2 id="导出格式" tabindex="-1">导出格式 <a class="header-anchor" href="#导出格式" aria-label="Permalink to &quot;导出格式&quot;">​</a></h2><ul><li><strong>JSON</strong> —— 完整的结构化数据。适合脚本处理、分析和重新导入。</li><li><strong>CSV</strong> —— 扁平的表格数据。可用 Excel、Google Sheets 或 pandas 打开。</li><li><strong>Markdown</strong> —— 格式化报告。可直接粘贴进文档、博客或 GitHub。</li><li><strong>JSONL</strong> —— 按行分隔的 JSON，用于导出训练数据。</li><li><strong>纯文本</strong> —— 朴素的对话记录。</li></ul><h2 id="如何导出" tabindex="-1">如何导出 <a class="header-anchor" href="#如何导出" aria-label="Permalink to &quot;如何导出&quot;">​</a></h2><ol><li>在任意结果页寻找<strong>导出</strong>按钮（下载图标）。</li><li>点击查看可用格式。</li><li>选择一种格式 —— 文件会立即下载。</li><li>如需分享：选择**「分享到 GitHub Discussions」**来发布你的发现。</li></ol><h2 id="分享到-github-discussions" tabindex="-1">分享到 GitHub Discussions <a class="header-anchor" href="#分享到-github-discussions" aria-label="Permalink to &quot;分享到 GitHub Discussions&quot;">​</a></h2><p>该功能在对比页和基准测试页可用。分享功能会用你的格式化报告预填一篇 GitHub Discussion 帖子。你可以补充自己的说明，并在发布前检查全部内容。没有你的明确操作，不会发送任何东西。</p><ol><li>在导出菜单中点击**「分享到 GitHub Discussions」**。</li><li>弹出对话框，显示 Markdown 报告的预览。</li><li>补充你的说明 —— 描述你发现了什么。</li><li>点击**「打开 GitHub Discussions」**，跳转到已预填报告的 GitHub 页面。</li><li>由你自己检查并提交帖子 —— 未经你同意不会发布任何内容。</li></ol><h2 id="数据隐私" tabindex="-1">数据隐私 <a class="header-anchor" href="#数据隐私" aria-label="Permalink to &quot;数据隐私&quot;">​</a></h2><blockquote><p>除非你主动选择分享，你的数据绝不会离开你的机器。所有导出都下载到你本地的文件系统。分享功能只是打开一个 GitHub 页面 —— 发布什么完全由你决定。</p></blockquote>',13)])])}const p=a(e,[["render",d]]);export{b as __pageData,p as default};
